                "title", "Comprovante de reserva",
                "reservationId", reservation.getId(),
                "guestName", reservation.getGuestName(),
                "guestCpf", reservation.getGuestCpf(),
                "roomNumber", reservation.getRoomNumber(),
                "roomType", reservation.getRoomNumber(),
                "checkIn", Formatters.formatDate(reservation.getCheckIn()),
                "checkOut", Formatters.formatDate(reservation.getCheckOut()),
