package br.marealta.integration;

import br.marealta.db.Database;
import br.marealta.db.MessageDAO;
import br.marealta.db.ReservationDAO;
import br.marealta.db.RoomDAO;
import br.marealta.model.RatePlan;
import br.marealta.model.Reservation;
import br.marealta.model.ReservationStatus;
import br.marealta.service.DefaultNotificationHandler;
import br.marealta.service.NotificationService;
import br.marealta.service.ReservationService;
import org.junit.Before;
import org.junit.Test;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.junit.Assert.*;

public class ReservationServiceTest {

    private static PostgreSQLContainer<?> postgres;
    private ReservationService reservationService;
    private ReservationDAO reservationDAO;

    @Before
    public void setUp() throws Exception {
        if (postgres == null) {
            postgres = new PostgreSQLContainer<>("postgres:18")
                .withDatabaseName("pousada_test")
                .withUsername("test")
                .withPassword("test");
            postgres.start();
        }

        System.setProperty("DB_URL", postgres.getJdbcUrl());
        System.setProperty("DB_USER", postgres.getUsername());
        System.setProperty("DB_PASSWORD", postgres.getPassword());

        System.setProperty("user.name", "test");
        System.setProperty("java.io.tmpdir", "/tmp");

        RoomDAO roomDAO = new RoomDAO(Database.getInstance());
        reservationDAO = new ReservationDAO(Database.getInstance());
        MessageDAO messageDAO = new MessageDAO(Database.getInstance());

        NotificationService notificationService = new NotificationService(messageDAO);
        notificationService.registerHandler(new DefaultNotificationHandler(notificationService));

        reservationService = new ReservationService(reservationDAO, roomDAO, notificationService);
    }

    @Test
    public void testCreateReservation() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.STANDARD);

        assertNotNull(res.getId());
        assertEquals(101, res.getRoomNumber());
        assertEquals("Test Guest", res.getGuestName());
        assertEquals(2, res.getNights());
        assertEquals(ReservationStatus.PENDING, res.getStatus());
        assertEquals(BigDecimal.ZERO, res.getAmountPaid());
    }

    @Test
    public void testConfirmReservation() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.STANDARD);

        BigDecimal amountPaid = res.getTotal();
        Reservation confirmed = reservationService.confirmReservation(res.getId(), amountPaid);

        assertEquals(ReservationStatus.CONFIRMED, confirmed.getStatus());
        assertEquals(amountPaid, confirmed.getAmountPaid());
    }

    @Test
    public void testCheckInCheckOut() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.STANDARD);

        reservationService.confirmReservation(res.getId(), res.getTotal());
        Reservation checkedIn = reservationService.checkIn(res.getId());
        assertEquals(ReservationStatus.CHECKED_IN, checkedIn.getStatus());

        Reservation checkedOut = reservationService.checkOut(res.getId());
        assertEquals(ReservationStatus.CHECKED_OUT, checkedOut.getStatus());
    }

    @Test
    public void testCancelReservationPending() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.STANDARD);

        Reservation cancelled = reservationService.cancelReservation(res.getId());
        assertEquals(ReservationStatus.CANCELLED, cancelled.getStatus());
        assertNull(cancelled.getRefund());
    }

    @Test
    public void testCancelReservationConfirmedStandard() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.STANDARD);

        reservationService.confirmReservation(res.getId(), res.getTotal());
        Reservation cancelled = reservationService.cancelReservation(res.getId());

        assertEquals(ReservationStatus.CANCELLED, cancelled.getStatus());
        assertEquals(res.getTotal(), cancelled.getRefund());
    }

    @Test
    public void testCancelReservationConfirmedNonRefundable() {
        Reservation res = reservationService.createReservation(
            101, "Test Guest", "test@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.NON_REFUNDABLE);

        reservationService.confirmReservation(res.getId(), res.getTotal());
        Reservation cancelled = reservationService.cancelReservation(res.getId());

        assertEquals(ReservationStatus.CANCELLED, cancelled.getStatus());
        assertEquals(BigDecimal.ZERO, cancelled.getRefund());
    }

    @Test
    public void testRoomUnavailable() {
        LocalDate checkIn = LocalDate.of(2027, 3, 10);
        LocalDate checkOut = LocalDate.of(2027, 3, 12);

        Reservation res1 = reservationService.createReservation(
            101, "Guest 1", "guest1@email.com", "123.456.789-00",
            checkIn, checkOut, 1, RatePlan.STANDARD);

        reservationService.confirmReservation(res1.getId(), res1.getTotal());

        try {
            reservationService.createReservation(
                101, "Guest 2", "guest2@email.com", "987.654.321-00",
                checkIn, checkOut, 1, RatePlan.STANDARD);
            fail("Should throw exception for unavailable room");
        } catch (IllegalArgumentException e) {
            assertEquals("ROOM_UNAVAILABLE", e.getMessage());
        }
    }

    @Test
    public void testCapacityExceeded() {
        try {
            reservationService.createReservation(
                101, "Guest", "guest@email.com", "123.456.789-00",
                LocalDate.of(2027, 3, 10),
                LocalDate.of(2027, 3, 12),
                3, RatePlan.STANDARD);
            fail("Should throw exception for capacity exceeded");
        } catch (IllegalArgumentException e) {
            assertEquals("CAPACITY_EXCEEDED", e.getMessage());
        }
    }

    @Test
    public void testHighSeasonPricing() {
        Reservation res = reservationService.createReservation(
            101, "Guest", "guest@email.com", "123.456.789-00",
            LocalDate.of(2027, 7, 10),
            LocalDate.of(2027, 7, 12),
            1, RatePlan.STANDARD);

        assertEquals(new BigDecimal("599.76"), res.getSubtotal());
        assertEquals(new BigDecimal("599.76"), res.getTotal());
    }

    @Test
    public void testNonRefundableDiscount() {
        Reservation res = reservationService.createReservation(
            101, "Guest", "guest@email.com", "123.456.789-00",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            1, RatePlan.NON_REFUNDABLE);

        assertEquals(new BigDecimal("499.80"), res.getSubtotal());
        assertEquals(new BigDecimal("74.97"), res.getDiscount());
        assertEquals(new BigDecimal("424.83"), res.getTotal());
    }
}

